#pragma once
#include <cstdint>
#include <functional>
#include <memory>
#include <string>
#include <vector>
#include <windows.h>
namespace nskry::record {
// Private encoder process only, bounded single decoded frame. MP4 generated by
// this plugin has no audio; this is an explicit re-encode, not keyframe remux.
void TrimRecording(const std::wstring &input, bool gif, UINT width, UINT height, int64_t start, int64_t end,
                   const std::function<void(const uint8_t *, int64_t, int64_t)> &write);
class PreviewDecoder {
  public:
    PreviewDecoder(std::wstring input, bool gif, UINT width, UINT height);
    ~PreviewDecoder();
    PreviewDecoder(const PreviewDecoder &) = delete;
    PreviewDecoder &operator=(const PreviewDecoder &) = delete;
    void Read(int64_t time, UINT outputWidth, UINT outputHeight, uint8_t *pixels);

  private:
    struct Impl;
    std::unique_ptr<Impl> m_impl;
    bool m_gif{};
};
} // namespace nskry::record
